from pathlib import Path
import re

def parse_events(path):
    text = Path(path).read_text()
    events = []
    for block in re.findall(r'BEGIN:VEVENT(.*?)END:VEVENT', text, re.S):
        d = {}
        for line in block.strip().splitlines():
            if ':' in line:
                k, v = line.split(':', 1)
                d[k.strip()] = v.strip()
        events.append((d.get('DTSTART'), d.get('DTEND')))
    return events

for p in ['/app/alice_calendar.ics','/app/bob_calendar.ics','/app/carol_calendar.ics']:
    print(p, parse_events(p))

